### 基础PDF文本提取

```rust
use pdf_extract::extract_text;
use regex::Regex;
use std::fs;
use anyhow::Result;

#[derive(Debug, Clone)]
pub struct Reference {
    pub authors: Vec<String>,
    pub title: String,
    pub journal: Option<String>,
    pub year: Option<u32>,
    pub volume: Option<String>,
    pub pages: Option<String>,
    pub doi: Option<String>,
    pub arxiv_id: Option<String>,
}

pub struct ReferenceExtractor {
    // 常见的参考文献格式正则表达式
    patterns: Vec<Regex>,
}

impl ReferenceExtractor {
    pub fn new() -> Result<Self> {
        let patterns = vec![
            // Nature/Science格式: Author, A. Title. Journal vol, pages (year).
            Regex::new(r"([A-Z][a-z]+(?:,\s*[A-Z]\.)+)\s+(.+?)\.\s*([A-Z][a-z\s]+)\s+(\d+),\s*(\d+(?:-\d+)?)\s*\((\d{4})\)")?,

            // Physical Review格式: A. Author, Title, Phys. Rev. X vol, pages (year)
            Regex::new(r"([A-Z]\.\s*[A-Z][a-z]+(?:,\s*[A-Z]\.\s*[A-Z][a-z]+)*),\s*(.+?),\s*(Phys\.\s*Rev\.\s*[A-Z]?)\s*(\d+),\s*(\d+)\s*\((\d{4})\)")?,

            // arXiv格式: Author et al., Title, arXiv:xxxx.xxxx
            Regex::new(r"([A-Z][a-z]+(?:\s+et\s+al\.)?),\s*(.+?),\s*arXiv:(\d{4}\.\d{4,5})")?,
        ];

        Ok(Self { patterns })
    }
}
```

## 高级解析策略

### 参考文献段落识别

```rust
impl ReferenceExtractor {
    pub fn extract_references(&self, pdf_path: &str) -> Result<Vec<Reference>> {
        // 1. 提取PDF文本
        let text = extract_text(pdf_path)?;

        // 2. 定位参考文献部分
        let references_section = self.find_references_section(&text)?;

        // 3. 分割单个引用
        let raw_references = self.split_references(&references_section);

        // 4. 解析每个引用
        let mut references = Vec::new();
        for raw_ref in raw_references {
            if let Some(parsed_ref) = self.parse_single_reference(&raw_ref) {
                references.push(parsed_ref);
            }
        }

        Ok(references)
    }

    fn find_references_section(&self, text: &str) -> Result<String> {
        // 查找References/Bibliography标题
        let section_markers = vec![
            r"(?i)references\s*\n",
            r"(?i)bibliography\s*\n", 
            r"(?i)works\s+cited\s*\n",
            r"\[\d+\]",  // 数字引用格式
        ];

        for marker in section_markers {
            let re = Regex::new(marker)?;
            if let Some(mat) = re.find(text) {
                return Ok(text[mat.start()..].to_string());
            }
        }

        anyhow::bail!("References section not found")
    }

    fn split_references(&self, section: &str) -> Vec<String> {
        // 基于编号模式分割 [1], [2], ... 或 1., 2., ...
        let split_patterns = vec![
            Regex::new(r"\n\[\d+\]").unwrap(),
            Regex::new(r"\n\d+\.").unwrap(),
            Regex::new(r"\n\(\d+\)").unwrap(),
        ];

        for pattern in split_patterns {
            let splits: Vec<&str> = pattern.split(section).collect();
            if splits.len() > 2 {  // 找到了分割模式
                return splits.into_iter()
                    .skip(1)  // 跳过第一个空段
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
            }
        }

        // fallback: 按双换行分割
        section.split("\n\n")
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect()
    }
}
```

### 物理学期刊特化解析

```rust
impl ReferenceExtractor {
    fn parse_physics_reference(&self, text: &str) -> Option<Reference> {
        // 专门处理物理学期刊格式

        // arXiv预印本识别
        if let Some(captures) = Regex::new(r"arXiv:(\d{4}\.\d{4,5})(?:v\d+)?")
            .unwrap().captures(text) {
            let arxiv_id = captures.get(1).unwrap().as_str();

            return Some(Reference {
                authors: self.extract_authors(text),
                title: self.extract_title_before_arxiv(text),
                journal: None,
                year: self.extract_year(text),
                volume: None,
                pages: None,
                doi: None,
                arxiv_id: Some(arxiv_id.to_string()),
            });
        }

        // Physical Review系列
        if text.contains("Phys. Rev.") {
            return self.parse_phys_rev_format(text);
        }

        // Journal of High Energy Physics (JHEP)
        if text.contains("JHEP") {
            return self.parse_jhep_format(text);
        }

        None
    }

    fn parse_phys_rev_format(&self, text: &str) -> Option<Reference> {
        let pattern = Regex::new(
            r"(.+?),\s*(.+?),\s*(Phys\.\s*Rev\.\s*[A-Z]?)\s*(\d+),\s*(\d+)\s*\((\d{4})\)"
        ).ok()?;

        let captures = pattern.captures(text)?;

        Some(Reference {
            authors: self.parse_author_list(captures.get(1)?.as_str()),
            title: captures.get(2)?.as_str().trim_matches('"').to_string(),
            journal: Some(captures.get(3)?.as_str().to_string()),
            year: captures.get(6)?.as_str().parse().ok(),
            volume: Some(captures.get(4)?.as_str().to_string()),
            pages: Some(captures.get(5)?.as_str().to_string()),
            doi: self.extract_doi(text),
            arxiv_id: None,
        })
    }
}
```

