## 完整应用示例

```rust
use clap::Parser;

#[derive(Parser)]
#[command(name = "ref-extractor")]
#[command(about = "Extract references from physics papers")]
struct Args {
    /// Input PDF file path
    #[arg(short, long)]
    input: String,

    /// Output JSON file path
    #[arg(short, long)]
    output: Option<String>,

    /// Use machine learning enhancement
    #[arg(long)]
    ml_enhance: bool,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    println!("🔍 Extracting references from: {}", args.input);

    let extractor = ReferenceExtractor::new()?;
    let references = extractor.extract_references(&args.input)?;

    println!("✅ Found {} references", references.len());

    // 输出结果
    if let Some(output_path) = args.output {
        let json = serde_json::to_string_pretty(&references)?;
        fs::write(output_path, json)?;
    } else {
        for (i, ref_item) in references.iter().enumerate() {
            println!("[{}] {} - {}", i+1, 
                ref_item.authors.join(", "), 
                ref_item.title);
        }
    }

    Ok(())
}
```

