## INSPIRE-HEP API客户端

```rust
use reqwest::Client;
use url::Url;

pub struct InspireClient {
    client: Client,
    base_url: String,
}

impl InspireClient {
    pub fn new() -> Self {
        Self {
            client: Client::new(),
            base_url: "https://inspirehep.net/api".to_string(),
        }
    }

    /// 通过arXiv ID获取论文记录
    pub async fn get_paper_by_arxiv(&self, arxiv_id: &str) -> anyhow::Result<Option<InspireRecord>> {
        // 清理arXiv ID格式 (支持 "2301.12345" 或 "arxiv:2301.12345")
        let clean_arxiv_id = arxiv_id
            .trim_start_matches("arxiv:")
            .trim_start_matches("arXiv:");

        let url = format!("{}/literature?q=arxiv:{}&size=1", 
                         self.base_url, clean_arxiv_id);

        let response = self.client
            .get(&url)
            .header("Accept", "application/json")
            .send()
            .await?;

        if !response.status().is_success() {
            anyhow::bail!("INSPIRE API request failed: {}", response.status());
        }

        let search_result: InspireSearchResult = response.json().await?;

        Ok(search_result.hits.hits.into_iter().next())
    }

    /// 获取论文的所有参考文献
    pub async fn get_references(&self, arxiv_id: &str) -> anyhow::Result<Vec<ProcessedReference>> {
        let paper = self.get_paper_by_arxiv(arxiv_id).await?;

        let paper = paper.ok_or_else(|| 
            anyhow::anyhow!("Paper with arXiv ID {} not found in INSPIRE", arxiv_id))?;

        let references = paper.metadata.references
            .unwrap_or_default();

        let mut processed_refs = Vec::new();

        for reference in references {
            if let Some(processed) = self.process_reference(reference).await {
                processed_refs.push(processed);
            }
        }

        Ok(processed_refs)
    }

    /// 处理单个参考文献，获取完整信息
    async fn process_reference(&self, reference: Reference) -> Option<ProcessedReference> {
        // 如果有INSPIRE记录链接，获取完整信息
        if let Some(record) = reference.record {
            if let Ok(detailed_ref) = self.get_detailed_reference(&record.ref_url).await {
                return Some(detailed_ref);
            }
        }

        // 否则使用原始引用信息
        if let Some(ref_details) = reference.reference {
            return Some(ProcessedReference::from_details(ref_details));
        }

        None
    }

    async fn get_detailed_reference(&self, ref_url: &str) -> anyhow::Result<ProcessedReference> {
        let response = self.client
            .get(ref_url)
            .header("Accept", "application/json")
            .send()
            .await?;

        let detailed_record: InspireRecord = response.json().await?;
        Ok(ProcessedReference::from_inspire_record(detailed_record))
    }
}

#[derive(Debug, Deserialize)]
struct InspireSearchResult {
    hits: InspireHits,
}

#[derive(Debug, Deserialize)]
struct InspireHits {
    hits: Vec<InspireRecord>,
    total: u32,
}
```

## 标准化参考文献结构

```rust
#[derive(Debug, Serialize, Clone)]
pub struct ProcessedReference {
    pub inspire_id: Option<u64>,
    pub title: String,
    pub authors: Vec<String>,
    pub arxiv_id: Option<String>,
    pub journal: Option<String>,
    pub volume: Option<String>,
    pub pages: Option<String>,
    pub year: Option<u32>,
    pub doi: Option<String>,
    pub citation_count: Option<u32>,
    pub categories: Vec<String>,
}

impl ProcessedReference {
    pub fn from_inspire_record(record: InspireRecord) -> Self {
        let metadata = record.metadata;

        let title = metadata.titles
            .and_then(|titles| titles.first().map(|t| t.title.clone()))
            .unwrap_or_else(|| "Unknown Title".to_string());

        let authors = metadata.authors
            .unwrap_or_default()
            .iter()
            .map(|author| author.full_name.clone())
            .collect();

        let arxiv_id = metadata.arxiv_eprints
            .and_then(|eprints| eprints.first().map(|e| e.value.clone()));

        let (journal, volume, pages, year) = if let Some(pub_info) = metadata.publication_info {
            let info = pub_info.first();
            (
                info.and_then(|p| p.journal_title.clone()),
                info.and_then(|p| p.journal_volume.clone()),
                info.and_then(|p| {
                    match (p.page_start.as_ref(), p.page_end.as_ref()) {
                        (Some(start), Some(end)) => Some(format!("{}-{}", start, end)),
                        (Some(start), None) => Some(start.clone()),
                        _ => None,
                    }
                }),
                info.and_then(|p| p.year),
            )
        } else {
            (None, None, None, None)
        };

        let doi = metadata.dois
            .and_then(|dois| dois.first().map(|d| d.value.clone()));

        let categories = metadata.arxiv_eprints
            .unwrap_or_default()
            .iter()
            .flat_map(|eprint| eprint.categories.as_ref().unwrap_or(&vec![]))
            .cloned()
            .collect();

        Self {
            inspire_id: Some(record.id),
            title,
            authors,
            arxiv_id,
            journal,
            volume,
            pages,
            year,
            doi,
            citation_count: None, // 需要额外API调用获取
            categories,
        }
    }
}
```

## 命令行工具实现

```rust
use clap::Parser;
use std::fs;

#[derive(Parser)]
#[command(name = "inspire-refs")]
#[command(about = "Extract references from arXiv papers via INSPIRE-HEP")]
struct Args {
    /// arXiv ID (e.g., "2301.12345" or "arxiv:2301.12345")
    #[arg(short, long)]
    arxiv_id: String,

    /// Output format: json, bibtex, or text
    #[arg(short, long, default_value = "text")]
    format: String,

    /// Output file path (default: stdout)
    #[arg(short = 'o', long)]
    output: Option<String>,

    /// Include citation counts (requires additional API calls)
    #[arg(long)]
    with_citations: bool,

    /// Filter by arXiv categories (e.g., "hep-th,hep-ph")
    #[arg(long)]
    categories: Option<String>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    println!("🔍 Fetching references for arXiv:{} from INSPIRE-HEP...", args.arxiv_id);

    let client = InspireClient::new();
    let references = client.get_references(&args.arxiv_id).await?;

    println!("✅ Found {} references", references.len());

    // 按类别过滤
    let filtered_refs = if let Some(filter_cats) = args.categories {
        let filter_categories: Vec<&str> = filter_cats.split(',').collect();
        references.into_iter()
            .filter(|ref_item| {
                ref_item.categories.iter()
                    .any(|cat| filter_categories.contains(&cat.as_str()))
            })
            .collect()
    } else {
        references
    };

    // 格式化输出
    let output_content = match args.format.as_str() {
        "json" => format_as_json(&filtered_refs)?,
        "bibtex" => format_as_bibtex(&filtered_refs),
        "text" => format_as_text(&filtered_refs),
        _ => anyhow::bail!("Unsupported format: {}", args.format),
    };

    // 输出结果
    if let Some(output_path) = args.output {
        fs::write(output_path, output_content)?;
        println!("📄 Results saved to file");
    } else {
        println!("{}", output_content);
    }

    Ok(())
}

fn format_as_json(references: &[ProcessedReference]) -> anyhow::Result<String> {
    Ok(serde_json::to_string_pretty(references)?)
}

fn format_as_bibtex(references: &[ProcessedReference]) -> String {
    references.iter()
        .enumerate()
        .map(|(i, ref_item)| {
            let entry_type = if ref_item.arxiv_id.is_some() && ref_item.journal.is_none() {
                "misc"
            } else {
                "article"
            };

            let key = ref_item.arxiv_id.as_ref()
                .map(|id| format!("arxiv:{}", id))
                .or_else(|| ref_item.inspire_id.map(|id| format!("inspire:{}", id)))
                .unwrap_or_else(|| format!("ref{}", i + 1));

            let mut bibtex = format!("@{}{{{};\n", entry_type, key);
            bibtex.push_str(&format!("  title = {{{}}},\n", ref_item.title));
            bibtex.push_str(&format!("  author = {{{}}},\n", ref_item.authors.join(" and ")));

            if let Some(ref arxiv_id) = ref_item.arxiv_id {
                bibtex.push_str(&format!("  eprint = {{{}}},\n", arxiv_id));
                bibtex.push_str("  archivePrefix = {arXiv},\n");
            }

            if let Some(ref journal) = ref_item.journal {
                bibtex.push_str(&format!("  journal = {{{}}},\n", journal));
            }

            if let Some(year) = ref_item.year {
                bibtex.push_str(&format!("  year = {{{}}},\n", year));
            }

            if let Some(ref doi) = ref_item.doi {
                bibtex.push_str(&format!("  doi = {{{}}},\n", doi));
            }

            bibtex.push_str("}\n");
            bibtex
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn format_as_text(references: &[ProcessedReference]) -> String {
    references.iter()
        .enumerate()
        .map(|(i, ref_item)| {
            let mut text = format!("[{}] ", i + 1);
            text.push_str(&ref_item.authors.join(", "));
            text.push_str(&format!(", \"{}\",", ref_item.title));

            if let Some(ref arxiv_id) = ref_item.arxiv_id {
                text.push_str(&format!(" arXiv:{}", arxiv_id));
            }

            if let Some(ref journal) = ref_item.journal {
                text.push_str(&format!(" {}", journal));
                if let Some(ref volume) = ref_item.volume {
                    text.push_str(&format!(" {}", volume));
                }
                if let Some(ref pages) = ref_item.pages {
                    text.push_str(&format!(", {}", pages));
                }
            }

            if let Some(year) = ref_item.year {
                text.push_str(&format!(" ({})", year));
            }

            if !ref_item.categories.is_empty() {
                text.push_str(&format!(" [{}]", ref_item.categories.join(", ")));
            }

            text
        })
        .collect::<Vec<_>>()
        .join("\n")
}
```

## 高级功能扩展

### 1. 引用网络分析

```rust
use std::collections::{HashMap, HashSet};

pub struct CitationNetwork {
    pub nodes: HashMap<String, ProcessedReference>,
    pub edges: Vec<(String, String)>, // (citing_paper, cited_paper)
}

impl InspireClient {
    pub async fn build_citation_network(&self, 
                                       root_arxiv_id: &str, 
                                       depth: usize) -> anyhow::Result<CitationNetwork> {
        let mut network = CitationNetwork {
            nodes: HashMap::new(),
            edges: Vec::new(),
        };

        let mut to_process = vec![(root_arxiv_id.to_string(), 0)];
        let mut processed = HashSet::new();

        while let Some((arxiv_id, current_depth)) = to_process.pop() {
            if processed.contains(&arxiv_id) || current_depth >= depth {
                continue;
            }

            processed.insert(arxiv_id.clone());

            if let Ok(references) = self.get_references(&arxiv_id).await {
                for reference in references {
                    if let Some(ref cited_arxiv) = reference.arxiv_id {
                        network.edges.push((arxiv_id.clone(), cited_arxiv.clone()));
                        network.nodes.insert(cited_arxiv.clone(), reference.clone());

                        if current_depth + 1 < depth {
                            to_process.push((cited_arxiv.clone(), current_depth + 1));
                        }
                    }
                }
            }
        }

        Ok(network)
    }
}
```

### 2. 缓存机制

```rust
use serde::{Serialize, Deserialize};
use std::collections::HashMap;
use std::path::Path;

#[derive(Serialize, Deserialize)]
pub struct InspireCache {
    papers: HashMap<String, InspireRecord>,
    references: HashMap<String, Vec<ProcessedReference>>,
    timestamp: u64,
}

impl InspireCache {
    pub fn load_or_create<P: AsRef<Path>>(path: P) -> Self {
        if path.as_ref().exists() {
            if let Ok(content) = std::fs::read_to_string(&path) {
                if let Ok(cache) = serde_json::from_str(&content) {
                    return cache;
                }
            }
        }

        Self {
            papers: HashMap::new(),
            references: HashMap::new(),
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
        }
    }

    pub fn save<P: AsRef<Path>>(&self, path: P) -> anyhow::Result<()> {
        let content = serde_json::to_string_pretty(self)?;
        std::fs::write(path, content)?;
        Ok(())
    }
}
```

## 使用示例

```bash
# 获取某篇论文的所有参考文献
cargo run -- --arxiv-id 2301.12345 --format json --output refs.json

# 只获取高能理论的参考文献
cargo run -- --arxiv-id 2301.12345 --categories "hep-th,hep-ph" --format bibtex

# 构建二层引用网络
cargo run -- --arxiv-id 2301.12345 --build-network --depth 2
```

这个方案的优势：

1. **数据质量高**：INSPIRE-HEP的数据经过专业整理
2. **格式标准化**：避免了PDF解析的不确定性
3. **元数据丰富**：包含分类、引用数等信息
4. **特别适合物理学**：[[高能物理]]、[[凝聚态物理]]、[[宇宙学]]等领域覆盖完善
5. **API稳定**：相比网页爬取更可靠

主要限制是依赖论文已被INSPIRE-HEP收录，但对于arXiv上的物理学论文，收录率很高。
